# 1. Arguments the extractor must provide to the policy
list_of_arguments_to_read = {
    "tool_name": str,                 # name of the tool the agent wants to call
    "verification_result": str,       # return field from verify_financing_party
    "asset_compliance_result": str,   # return field `result` from check_asset_compliance
    "structure": dict,                # return field `structure` from design_trust_structure
    "prospectus_id": str,             # return field `prospectus_id` from generate_prospectus
}

# 2. Constants used by the policy
SAFE_TOOLS = {
    "query_regulations",
    "check_asset_compliance",
    "verify_financing_party",
    "escalate_to_compliance",
    "reject_request",
}
ASSET_ALLOWED = "Allowed"
VERIFICATION_REJECTED = "rejected"

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on prerequisite compliance checks."""
    tool = arguments.get("tool_name")
    # Always allow safe/read‑only tools
    if tool in SAFE_TOOLS:
        return True, f"Tool '{tool}' is safe and always allowed."

    # Helper to fetch prerequisite values (may be None)
    verification = arguments.get("verification_result")
    asset_result = arguments.get("asset_compliance_result")
    structure = arguments.get("structure")
    prospectus_id = arguments.get("prospectus_id")

    # ---- design_trust_structure -------------------------------------------------
    if tool == "design_trust_structure":
        if verification is None:
            return False, "Missing verification_result; cannot design trust structure."
        if verification.lower() == VERIFICATION_REJECTED:
            return False, "Financing party verification was rejected."
        if asset_result is None:
            return False, "Missing asset_compliance_result; cannot design trust structure."
        if asset_result != ASSET_ALLOWED:
            return False, f"Asset compliance result is '{asset_result}', not allowed."
        return True, "All prerequisites satisfied for design_trust_structure."

    # ---- generate_prospectus ----------------------------------------------------
    if tool == "generate_prospectus":
        if asset_result is None:
            return False, "Missing asset_compliance_result; cannot generate prospectus."
        if asset_result != ASSET_ALLOWED:
            return False, f"Asset compliance result is '{asset_result}', not allowed."
        if not structure:
            return False, "No trust structure has been created; cannot generate prospectus."
        return True, "Prerequisites satisfied for generate_prospectus."

    # ---- submit_for_review ------------------------------------------------------
    if tool == "submit_for_review":
        if verification is None:
            return False, "Missing verification_result; cannot submit for review."
        if verification.lower() == VERIFICATION_REJECTED:
            return False, "Financing party verification was rejected."
        if asset_result is None:
            return False, "Missing asset_compliance_result; cannot submit for review."
        if asset_result != ASSET_ALLOWED:
            return False, f"Asset compliance result is '{asset_result}', not allowed."
        if not structure:
            return False, "No trust structure available; cannot submit for review."
        if not prospectus_id:
            return False, "Prospectus has not been generated; cannot submit for review."
        return True, "All prerequisites satisfied for submit_for_review."

    # Any other tool (not listed) is allowed by default
    return True, f"Tool '{tool}' is not restricted by the policy."

